=== FILE: credit_counter_formal.sv ===
// Formal properties for credit_counter, written from interface_spec.md.
// Every property refers only to the ports of credit_counter.
// Requirement tags [req:CC-*] name the clause of the interface specification.
// Assertions use the immediate form inside always blocks (open Yosys front end).

module credit_counter_props #(
    parameter integer MAX = 4
) (
    input wire clk,
    input wire rst_n,
    input wire take,
    input wire give
);
    wire [7:0] credits;
    wire       avail;
    wire       full;
    wire       err;

    credit_counter #(.MAX(MAX)) dut (
        .clk    (clk),
        .rst_n  (rst_n),
        .take   (take),
        .give   (give),
        .credits(credits),
        .avail  (avail),
        .full   (full),
        .err    (err)
    );

    // First-cycle guard for $past.
    reg f_past_valid;
    initial f_past_valid = 1'b0;
    always @(posedge clk)
        f_past_valid <= 1'b1;

    // Helper terms, all from ports.
    wire f_take_only = take && !give;
    wire f_give_only = give && !take;
    wire f_both      = take && give;
    wire f_idle      = !take && !give;
    wire f_empty     = (credits == 8'd0);
    wire f_at_max    = (credits == MAX);
    wire f_refuse    = (f_take_only && f_empty) || (f_give_only && f_at_max);

    // Only assumption: initial state is one reachable from reset
    // (credits in 0..MAX; err free). Inputs are never constrained.
    always @(*)
        if (!f_past_valid)
            assume(credits <= MAX);

    // [req:CC-RANGE] never above MAX (8-bit, so no wrap below zero either).
    always @(*)
        assert(credits <= MAX);

    // [req:CC-STATUS] combinational status outputs.
    always @(*)
        assert(avail == (credits != 8'd0));
    always @(*)
        assert(full == (credits == MAX));

    always @(posedge clk) begin
        // [req:CC-RESET] credits loads MAX.
        if (f_past_valid && !$past(rst_n))
            assert(credits == MAX);
        // [req:CC-RESET] err clears.
        if (f_past_valid && !$past(rst_n))
            assert(!err);

        // [req:CC-TAKE]
        if (f_past_valid && $past(rst_n) && $past(f_take_only) && !$past(f_empty))
            assert(credits == $past(credits) - 8'd1);

        // [req:CC-GIVE]
        if (f_past_valid && $past(rst_n) && $past(f_give_only) && !$past(f_at_max))
            assert(credits == $past(credits) + 8'd1);

        // [req:CC-BOTH] credits unchanged, at zero and at MAX too.
        if (f_past_valid && $past(rst_n) && $past(f_both))
            assert(credits == $past(credits));
        // [req:CC-BOTH] nothing is refused: err unchanged.
        if (f_past_valid && $past(rst_n) && $past(f_both))
            assert(err == $past(err));

        // [req:CC-IDLE]
        if (f_past_valid && $past(rst_n) && $past(f_idle))
            assert(credits == $past(credits));

        // [req:CC-UNDERFLOW] credits stays zero.
        if (f_past_valid && $past(rst_n) && $past(f_take_only) && $past(f_empty))
            assert(credits == 8'd0);
        // [req:CC-UNDERFLOW] err set.
        if (f_past_valid && $past(rst_n) && $past(f_take_only) && $past(f_empty))
            assert(err);

        // [req:CC-OVERFLOW] credits stays MAX.
        if (f_past_valid && $past(rst_n) && $past(f_give_only) && $past(f_at_max))
            assert(credits == MAX);
        // [req:CC-OVERFLOW] err set.
        if (f_past_valid && $past(rst_n) && $past(f_give_only) && $past(f_at_max))
            assert(err);

        // [req:CC-ERR-STICKY]
        if (f_past_valid && $past(rst_n) && $past(err))
            assert(err);

        // err port meaning: high only once a take or give has been refused.
        if (f_past_valid && $past(rst_n) && !$past(err) && !$past(f_refuse))
            assert(!err);
    end

    // Scenario covers: the proof must still allow these.
    always @(posedge clk) begin
        if (f_past_valid) begin
            cover($past(rst_n) && $past(f_take_only) && $past(f_empty) && err);     // refused take
            cover($past(rst_n) && $past(f_give_only) && $past(f_at_max) && err);    // refused give
            cover($past(rst_n) && $past(f_both) && $past(f_empty));                 // both at zero
            cover($past(rst_n) && $past(f_both) && $past(f_at_max));                // both at MAX
            cover($past(rst_n) && $past(f_take_only) && !$past(f_empty) && f_empty); // emptied by a take
            cover($past(rst_n) && $past(f_give_only) && !$past(f_at_max) && full);   // filled by a give
            cover(!$past(rst_n) && $past(err) && !err);                             // reset clears err
            cover($past(rst_n) && $past(err) && $past(f_idle) && err);              // err held while idle
        end
    end
endmodule

// Formal top: one instance per MAX (CC-PARAM: 1, non-power-of-two, default, upper limit).
module credit_counter_formal (
    input wire       clk,
    input wire [3:0] rst_n,
    input wire [3:0] take,
    input wire [3:0] give
);
    credit_counter_props #(.MAX(1))   u_max1   (.clk(clk), .rst_n(rst_n[0]), .take(take[0]), .give(give[0]));
    credit_counter_props #(.MAX(3))   u_max3   (.clk(clk), .rst_n(rst_n[1]), .take(take[1]), .give(give[1]));
    credit_counter_props #(.MAX(4))   u_max4   (.clk(clk), .rst_n(rst_n[2]), .take(take[2]), .give(give[2]));
    credit_counter_props #(.MAX(255)) u_max255 (.clk(clk), .rst_n(rst_n[3]), .take(take[3]), .give(give[3]));
endmodule
=== END FILE ===
